function numberToText(num) {
    if (num === 0) return 'không'

    const dv = ['', 'một', 'hai', 'ba', 'bốn', 'năm', 'sáu', 'bảy', 'tám', 'chín']
    const hang = ['', 'nghìn', 'triệu', 'tỷ']

    function read3Digits(n, full) {
        let tram = Math.floor(n / 100)
        let chuc = Math.floor((n % 100) / 10)
        let donvi = n % 10
        let str = ''

        if (full || tram > 0) {
            str += dv[tram] + ' trăm'
            if (chuc === 0 && donvi > 0) str += ' lẻ'
        }

        if (chuc > 1) {
            str += ' ' + dv[chuc] + ' mươi'
            if (donvi === 1) str += ' mốt'
            else if (donvi === 5) str += ' lăm'
            else if (donvi > 0) str += ' ' + dv[donvi]
        } else if (chuc === 1) {
            str += ' mười'
            if (donvi === 5) str += ' lăm'
            else if (donvi > 0) str += ' ' + dv[donvi]
        } else if (chuc === 0 && donvi > 0) {
            str += ' ' + dv[donvi]
        }

        return str.trim()
    }

    let str = ''
    let i = 0
    let full = false

    while (num > 0) {
        let block = num % 1000
        if (block > 0) {
            let tmp = read3Digits(block, full)
            str = tmp + ' ' + hang[i] + ' ' + str
            full = true
        } else {
            full = true
        }
        num = Math.floor(num / 1000)
        i++
    }

    return str.trim().replace(/\s+/g, ' ')
}

// Hàm loại bỏ các từ khóa học hàm/học vị khỏi chuỗi văn bản
function removeHocHam(text) {
    if (typeof text !== 'string') {
        return text
    }

    var wordsToRemove = ['Thạc sĩ,', 'Thạc sĩ', 'Cao học,', 'Cao học']

    // Tạo regex từ mảng từ khóa để tìm và thay thế (không phân biệt hoa thường)
    var regex = new RegExp(wordsToRemove.join('|'), 'gi')

    // Thay thế từ khóa bằng chuỗi rỗng
    var newText = text.replace(regex, '')
    // Loại bỏ khoảng trắng thừa
    newText = newText.replace(/\s+/g, ' ').trim()

    return newText
}

function removeKhoaID(str) {
    if (!str) {
        return ""
    }

    return str.replace(/\(PSD\)|\(KDU\)/g, "").trim()
}

function ajaxCALLPromise(url, params = null) {
    return new Promise((resolve) => {
        ajaxCALL(
            url,
            params,
            (res) => resolve(res.data),
            (error) => {
                console.error("CALL Error:", error);
                const errMsg = error && error.responseJSON && error.responseJSON.Message
                    ? error.responseJSON.Message
                    : "Lỗi thực hiện tác vụ";
                if (typeof Vue !== "undefined" && Vue.$toast) {
                    Vue.$toast.error(errMsg, { position: "top" });
                }
                resolve(null);
            }
        );
    });
}
function ajaxGETCALLPromise(url, params = null) {
    return new Promise((resolve) => {
        const headers = {
            "Content-Type": "application/json; charset=utf-8"
        };
        if (typeof $awt !== "undefined" && $awt) {
            headers["Authorization"] = $awt;
        }
        $.ajax({
            url: url,
            type: "GET",
            data: params,
            headers: headers,
            success: (res) => resolve(res),
            error: (err) => {
                console.error("GET Error:", err);
                const errMsg = err.responseJSON && err.responseJSON.Message 
                    ? err.responseJSON.Message 
                    : "Lỗi kết nối máy chủ";
                if (typeof Vue !== "undefined" && Vue.$toast) {
                    Vue.$toast.error(errMsg, { position: "top" });
                }
                resolve(null);
            }
        });
    });
}

function ajaxPOSTBlobPromise(url, data = null) {
    return new Promise((resolve) => {
        $.ajax({
            url: url,
            type: "POST",
            contentType: "application/json",
            data: JSON.stringify(data),
            xhrFields: {
                responseType: "blob"
            },
            success: (res) => resolve(res),
            error: (err) => {
                console.error("Export File Error:", err);
                if (typeof Vue !== "undefined" && Vue.$toast) {
                    Vue.$toast.error("Lỗi khi tải file", { position: "top" });
                }
                resolve(null);
            }
        });
    });
}

let _cachedNganhCaoHoc = null;

async function getNganhCaoHocPromise({ hasAllOption = false } = {}) {
    if (!_cachedNganhCaoHoc) {
        const res = await ajaxGETCALLPromise("https://tapi.lhu.edu.vn/hoso/SDH_SelectNganh_CaoHoc");
        const list = (res && res.data) ? res.data : [];

        _cachedNganhCaoHoc = list.map((item, index, array) => {
            if (item.TenNganh === 'Tài chính ngân hàng' || item.NganhID == 40) {
                item.TenNganh = 'Tài chính - Ngân hàng';
            }

            const isDuplicate = array.some(
                (el, i) => i !== index && el.TenNganh.toLowerCase() === item.TenNganh.toLowerCase()
            );
            const rawName = isDuplicate ? `${item.TenNganh} (${item.KhoaID})` : item.TenNganh;
            const cleanName = typeof removeHocHam === "function" ? removeHocHam(rawName) : rawName;

            return {
                ...item,
                NganhID: item.NganhID,
                TenNganh: cleanName,
                TenNganhHienThi: cleanName,
                OriginalName: isDuplicate ? item.TenNganh : "",
            };
        });

        if (typeof window !== "undefined") {
            if (!window.vueData) window.vueData = {};
            window.vueData.NganhGlobal = _cachedNganhCaoHoc;
            window.vueData.NganhGiangDay = _cachedNganhCaoHoc;
        }
    }

    if (hasAllOption) {
        return [{ NganhID: 0, TenNganh: "- Tất cả -", TenNganhHienThi: "- Tất cả -" }, ..._cachedNganhCaoHoc];
    }
    return [..._cachedNganhCaoHoc];
}

/**
 * Tự động lọc thanh Menu dựa trên vai trò đào tạo (Cao học - Master vs Nghiên cứu sinh - Phd)
 * Dành cho nhóm tài khoản học viên (GroupID = 2) dựa trên vueData.ClassID
 * Quy tắc:
 *   - "22CC912": chữ C sau 22 -> Thạc sĩ (Master)
 *   - "26NQ913": chữ N sau 26 -> Tiến sĩ (Phd)
 */
(function autoFilterStudentMenuByRole() {
    if (typeof window === "undefined") return;

    let retryCount = 0;
    const maxRetries = 30;

    function applyFilter(heDaoTao) {
        const menu = window.vueData?.v_Set?.menu;
        if (!Array.isArray(menu)) return;

        const isPhd = String(heDaoTao).toLowerCase() === 'phd';
        for (let i = menu.length - 1; i >= 0; i--) {
            const item = menu[i];
            if (isPhd && item.roleCode === 'Master') {
                menu.splice(i, 1);
            } else if (!isPhd && item.roleCode === 'Phd') {
                menu.splice(i, 1);
            }
        }
    }

    function checkUserAndFilter() {
        const user = window.vueData?.user;
        const menu = window.vueData?.v_Set?.menu;
        const classId = window.vueData?.ClassID || user?.ClassID;

        if (!user || !user.UserID || !menu) {
            retryCount++;
            if (retryCount < maxRetries) {
                setTimeout(checkUserAndFilter, 200);
            }
            return;
        }

        const rawGroup = user.GroupID;
        const groupList = Array.isArray(rawGroup) ? rawGroup : [rawGroup];
        const isStudent = groupList.some(g => String(g) === '2');
        if (!isStudent) return;

        if (!classId) {
            retryCount++;
            if (retryCount < maxRetries) {
                setTimeout(checkUserAndFilter, 200);
                return;
            }
        }

        // Lấy ký tự ngay sau 2 số đầu tiên (hoặc ký tự thứ 3 của mã lớp)
        const str = String(classId || '').trim().toUpperCase();
        const match = str.match(/^\d{2}([A-Z])/);
        const typeChar = match ? match[1] : str.charAt(2);
        const heDaoTao = (typeChar === 'N') ? 'Phd' : 'Master';

        applyFilter(heDaoTao);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', checkUserAndFilter);
    } else {
        checkUserAndFilter();
    }
})();